<script setup lang="ts">
import {computed,ref} from 'vue'
import {useRoute} from 'vue-router'
import {get} from '../api/http'
import type {Row} from '../api/types'
import {useMediaQuery} from '../composables/useMediaQuery'
import {useAuth} from '../stores/auth'
import {useResource,useMutation,deleteEntity,money} from '../composables/useResource'
import {usePagedResource} from '../composables/usePagedResource'
import ExchangeActions from '../components/ExchangeActions.vue'
import RelatedRecords from '../components/RelatedRecords.vue'
import PageHeader from '../components/PageHeader.vue'
import ResourceState from '../components/ResourceState.vue'
import DataTable,{type Column} from '../components/DataTable.vue'
import EntityDialog,{type Field} from '../components/EntityDialog.vue'
const route=useRoute(),auth=useAuth(),kind=computed(()=>String(route.meta.key)),endpoint=computed(()=>`/${kind.value}`)
const config=computed(()=>({suppliers:{title:'供应商管理',singular:'供应商',subtitle:'维护合作伙伴档案、资质与采购履约记录。',columns:[{key:'code',label:'供应商编号'},{key:'name',label:'供应商名称',minWidth:220},{key:'contact',label:'联系人'},{key:'phone',label:'联系电话'},{key:'category',label:'供应类别'},{key:'rating',label:'评级',number:true},{key:'status',label:'状态',status:true}],fields:[{key:'code',label:'供应商编号',required:true},{key:'name',label:'供应商名称',required:true},{key:'contact',label:'联系人'},{key:'phone',label:'联系电话'},{key:'category',label:'供应类别'},{key:'rating',label:'评级（0–5）',kind:'number',max:5},{key:'qualification',label:'资质信息',kind:'textarea',span:2},{key:'qualification_expiry',label:'资质有效期',kind:'date'},{key:'status',label:'合作状态',kind:'select',required:true,options:[{label:'合作中',value:'ACTIVE'},{label:'停用',value:'INACTIVE'}]}]},materials:{title:'材料档案',singular:'材料',subtitle:'统一材料编码、规格与计量单位，为采购和仓储建立一致标准。',columns:[{key:'code',label:'材料编码'},{key:'name',label:'材料名称',minWidth:180},{key:'specification',label:'规格型号',minWidth:180},{key:'unit',label:'单位',width:80},{key:'category',label:'材料分类'},{key:'safety_stock',label:'安全库存',number:true},{key:'reference_price',label:'参考单价（元）',money:true,minWidth:155}],fields:[{key:'code',label:'材料编码',required:true},{key:'name',label:'材料名称',required:true},{key:'specification',label:'规格型号'},{key:'unit',label:'计量单位',required:true},{key:'category',label:'材料分类',required:true},{key:'safety_stock',label:'安全库存',kind:'number',required:true},{key:'reference_price',label:'参考单价（元）',kind:'money',required:true}]},warehouses:{title:'仓库管理',singular:'仓库',subtitle:'维护实体仓库和现场库房，建立清晰的库存归属。',columns:[{key:'code',label:'仓库编码'},{key:'name',label:'仓库名称'},{key:'location',label:'仓库地址',minWidth:300}],fields:[{key:'code',label:'仓库编码',required:true},{key:'name',label:'仓库名称',required:true},{key:'location',label:'仓库地址',span:2}]}} as Record<string,{title:string;singular:string;subtitle:string;columns:Column[];fields:Field[]}>)[kind.value]!)
const listing=usePagedResource(()=>`/records/${kind.value}`),{data,loading,error,load,paging,onPage,onSize,onSearch}=listing,dialog=ref(false),selected=ref<Row>(),drawer=ref(false),detail=ref<any>(),detailLoading=ref(false),detailError=ref('')
const {saving,run}=useMutation(load)
function supplierStatus(value?:string){return value==='ACTIVE'?'合作中':value==='INACTIVE'?'已停用':value||'—'}
function edit(row?:Row){selected.value=row;dialog.value=true}
async function drop(row:Row){await run(()=>deleteEntity(endpoint.value,row.id),'档案已处理')}
async function supplierDetail(row:Row){selected.value=row;drawer.value=true;detailLoading.value=true;detail.value=null;detailError.value='';try{detail.value=await get(`/suppliers/${row.id}`)}catch(e){detailError.value=e instanceof Error?e.message:'加载失败'}finally{detailLoading.value=false}}
const isMobile=useMediaQuery()
</script>
<template><PageHeader :title="config.title" :subtitle="config.subtitle"><ExchangeActions :entity="kind" :filters="{q:paging.q}" :allow-import="auth.can('master:write')" @changed="load"/><el-button :loading="loading" @click="load">刷新</el-button><el-button v-if="auth.can('master:write')" type="primary" @click="edit()">＋ 新增{{config.singular}}</el-button></PageHeader><section class="panel table-panel"><ResourceState :loading="loading" :error="error" @retry="load"><DataTable :remote="paging" @page="onPage" @size="onSize" @search="onSearch" :rows="data" :columns="config.columns" :action-width="kind==='suppliers'?210:150"><template #status="{row}"><el-tag :type="row.status==='ACTIVE'?'primary':'info'" effect="light" round size="small">{{supplierStatus(row.status)}}</el-tag></template><template #actions="{row}"><el-button v-if="kind==='suppliers'" link type="primary" @click="supplierDetail(row)">详情</el-button><el-button v-if="auth.can('master:write')" link type="primary" @click="edit(row)">编辑</el-button><el-button v-if="kind!=='warehouses'&&auth.can('master:write')" link type="danger" :disabled="saving" @click="drop(row)">删除</el-button></template></DataTable></ResourceState></section><EntityDialog v-model="dialog" :title="`${selected?'编辑':'新增'}${config.singular}`" :endpoint="endpoint" :record="selected" :fields="config.fields" :defaults="{status:'ACTIVE',rating:4.5,reference_price:'0',safety_stock:0}" @saved="load"/><el-drawer v-model="drawer" title="供应商详情" :size="isMobile?'100%':'820px'" class="supplier-drawer"><ResourceState :loading="detailLoading" :error="detailError" @retry="selected&&supplierDetail(selected)"><template v-if="detail?.supplier"><div class="detail-banner"><div><el-tag :type="detail.supplier.status==='ACTIVE'?'primary':'info'" effect="light" round size="small">{{supplierStatus(detail.supplier.status)}}</el-tag><h2>{{detail.supplier.name}}</h2><p>{{detail.supplier.code}} · {{detail.supplier.category}}</p></div></div><el-descriptions :column="isMobile?1:2" border><el-descriptions-item label="联系人">{{detail.supplier.contact}}</el-descriptions-item><el-descriptions-item label="联系电话">{{detail.supplier.phone}}</el-descriptions-item><el-descriptions-item label="资质信息">{{detail.supplier.qualification||'—'}}</el-descriptions-item><el-descriptions-item label="有效期">{{detail.supplier.qualification_expiry||'—'}}</el-descriptions-item><el-descriptions-item label="合作评级">{{detail.supplier.rating}}</el-descriptions-item></el-descriptions><div v-if="detail.metrics" class="mini-metrics"><div v-for="(v,k) in detail.metrics" :key="k"><span>{{({order_amount:'采购金额',paid_amount:'净实付金额',payable_amount:'退货后应付',refund_due_amount:'待收退款',outstanding_amount:'应付未付',quote_count:'报价次数',order_count:'订单数量'} as Record<string,string>)[k]||k}}</span><b>{{String(k).includes('count')?v:money(v)}}</b></div></div><el-tabs><el-tab-pane v-if="auth.can('quote:read')" label="历史报价"><RelatedRecords entity="quotes" :filters="{supplier_id:detail.supplier.id}" :columns="[{key:'request_code',label:'采购申请'},{key:'total_amount',label:'报价金额',money:true},{key:'delivery_days',label:'交货天数'},{key:'valid_until',label:'有效期'}]"/></el-tab-pane><el-tab-pane v-if="auth.can('order:read')" label="采购订单"><RelatedRecords entity="orders" :filters="{supplier_id:detail.supplier.id}" :columns="[{key:'code',label:'订单号'},{key:'project_name',label:'所属项目'},{key:'total_amount',label:'订单金额',money:true},{key:'status',label:'状态',status:true}]" destination="/orders/:id"/></el-tab-pane></el-tabs></template></ResourceState></el-drawer></template>
